content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-12-finance-001

=== 用户原始指令 (query.txt) ===
整个图给我，数字会变，点打电话，读天气，红色警告

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个图给我，数字会变，点打电话，读天气，红色警告",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToCallPhone",
      "args": {
        "phoneNumber": "10086"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称。",
            "sampleValue": "青浦"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本，会随天气能力结果变化。",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "雷阵雨"
          },
          "alertLevel": {
            "type": "string",
            "description": "当前天气预警等级或预警摘要。",
            "sampleValue": "红色预警"
          }
        }
      }
    },
    "contact": {
      "phoneNumber": {
        "type": "string",
        "description": "点击电话入口时拨打的服务号码。",
        "sampleValue": "10086"
      }
    },
    "state": {
      "loading": {
        "type": "boolean",
        "description": "天气数据加载状态。",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/thunderstorm.png",
      "description": "雷暴天气彩色图标，适合表达强天气、雷雨和天气预警主视觉。"
    },
    {
      "src": "resources/base/media/phone_fill.svg",
      "description": "电话听筒实心图标，适合表达拨打电话动作入口。"
    }
  ]
}

